function renderFlow() {
  const currentStep = Number(appsmith.model?.currentStep ?? 0);
  const steps = document.querySelectorAll(".flow-step");
  const connectors = document.querySelectorAll(".connector");

  /* =========================================
     UPDATE STEPS
     ========================================= */

  steps.forEach(step => {
    const stepNumber = Number(step.dataset.step);

    /* Remove dynamic states */
    step.classList.remove("is-completed", "is-current", "is-future");

    /* Step 2 is permanently reserved */
    if (stepNumber === 2) {
      return;
    }

    /* Completed */
    if (stepNumber < currentStep) {
      step.classList.add("is-completed");
    }

    /* Current */else if (stepNumber === currentStep) {
      step.classList.add("is-current");
    }

    /* Future */else {
      step.classList.add("is-future");
    }
  });

  /* =========================================
     UPDATE CONNECTORS
     ========================================= */

  connectors.forEach((connector, index) => {
    /* Remove previous dynamic state */
    connector.classList.remove("is-completed");

    /*
     * Connector index represents the
     * transition to the next step.
     *
     * 0 = 0 → 1
     * 1 = 1 → 2
     * 2 = 2 → 3
     * 3 = 3 → 4
     * 4 = 4 → 5
     * 5 = 5 → 6
     * 6 = 6 → 7
     */

    if (index < currentStep) {
      connector.classList.add("is-completed");
    }
  });
}

/* =========================================
   APP READY
   ========================================= */

appsmith.onReady(() => {
  renderFlow();
});

/* =========================================
   MODEL CHANGE
   ========================================= */

appsmith.onModelChange(() => {
  renderFlow();
});

